//function to conjugate a regular verb in present tense
function presentTense(verb) {
  return verb;
}
//function to conjugate a regular verb in past tense
function pastTense(verb) {
  if (verb.slice(-1) === "e") {
    return verb + "d";
  } else {
    return verb + "ed";
  }
}
//function to conjugate a regular verb in past participle
function pastParticiple(verb) {
  if (verb.slice(-1) === "e") {
    return verb + "d";
  } else {
    return verb + "ed";
  }
}
//example of using the functions to conjugate a regular verb
