func analyzeArtworkEmotions(image: UIImage) -> [String] {
    var emotions = [String]()

    guard let ciImage = CIImage(image: image) else { return emotions }
    guard let model = try? VNCoreMLModel(for: EmotionClassifier().model) else { return emotions }
