Here is the Java code to implement this program:
```java
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
public class OddWordIdentifier {
    public static void main(String[] args) {
        List<String> colors = Arrays.asList("red", "orange", "yellow", "green", "blue", "purple");
        List<String> foods = Arrays.asList("pizza", "hamburger", "hotdog", "sushi", "spaghetti", "taco");
        List<String> sentences = Arrays.asList("The sky is blue", "I like to eat pizza", "The moon is bright tonight");
        for (String sentence : sentences) {
            String[] words = sentence.split(" ");
            List<String> oddWords = new ArrayList<>();
            for (String word : words) {
                if (!colors.contains(word) && !foods.contains(word)) {
                    oddWords.add(word);
                }
            }
            System.out.println("Odd word(s) in \"" + sentence + "\": " + oddWords);
        }
    }
}
