#include <cmath>
class Sun {
private:
    const double mass = 1.989e30; // kg
    const double radius = 6.963e8; // m
    const double luminosity = 3.828e26; // W
    const double temperature = 5778; // K
public:
    void personify() {
        std::cout << "I am the brilliant sun, giver of life to all living beings on Earth.\n";
    }
    double getMass() const {
        return mass;
    }
    double getRadius() const {
        return radius;
    }
    double getLuminosity() const {
        return luminosity;
    }
    double getTemperature() const {
        return temperature;
    }
    double getSurfaceGravity() const {
        const double G = 6.6743e-11; // m^3 / (kg * s^2)
        return G * mass / std::pow(radius, 2);
    }
    double getEscapeVelocity() const {
        const double G = 6.6743e-11; // m^3 / (kg * s^2)
        return std::sqrt(2 * G * mass / radius);
    }
    double getCoreTemperature() const {
        const double gamma = 5.0 / 3.0;
        const double k_B = 1.380649e-23; // m^2 * kg / (s^2 * K)
        const double mu = 0.61; // average molecular weight of ionized gas
        const double rho = 150.0; // kg / m^3 (typical density of sun's core)
        const double T_c = temperature * std::pow((gamma - 1) * luminosity / (4 * M_PI * std::pow(radius, 2) * k_B * mu * rho), 1.0 / 4.0);
