Can you provide a more complex C++ code to implement a class for a linked list data structure that includes methods for inserting, deleting, and sorting nodes? Please also provide an example of how to sort the nodes in ascending order using this class. Additionally, can you explain the time and space complexity of each method and suggest any optimizations to improve performance? 
[C++ code]
class LinkedList {
private:
    struct Node {
        int data;
        Node* next;
    };
    Node* head;
public:
    LinkedList() {
        head = nullptr;
    }
    void insert(int value) {
        Node* newNode = new Node;
        newNode->data = value;
        newNode->next = head;
        head = newNode;
    }
    void remove(int value) {
        Node* currNode = head;
        Node* prevNode = nullptr;
        while (currNode != nullptr) {
            if (currNode->data == value) {
                if (prevNode == nullptr) {
                    head = currNode->next;
                } else {
                    prevNode->next = currNode->next;
                }
                delete currNode;
                return;
            }
            prevNode = currNode;
            currNode = currNode->next;
        }
    }
    void sort() {
        if (head == nullptr || head->next == nullptr) {
            return;
        }
        Node* currNode = head;
        while (currNode != nullptr) {
            Node* nextNode = currNode->next;
            while (nextNode != nullptr) {
                if (currNode->data > nextNode->data) {
                    int temp = currNode->data;
                    currNode->data = nextNode->data;
                    nextNode->data = temp;
                }
                nextNode = nextNode->next;
            }
            currNode = currNode->next;
        }
    }
};

