```
struct Employee {
    var name: String
    var department: String
    var location: String
    var lengthOfService: Int // in years
}
func averageLengthOfService(employees: [Employee]) -> [String: [String: Double]] {
    var departmentAverages: [String: [String: (totalLength: Int, count: Int)]] = [:]
    for employee in employees {
        if departmentAverages[employee.department] == nil {
            departmentAverages[employee.department] = [:]
        }
        if departmentAverages[employee.department]![employee.location] == nil {
            departmentAverages[employee.department]![employee.location] = (0, 0)
        }
        departmentAverages[employee.department]![employee.location]!.totalLength += employee.lengthOfService
        departmentAverages[employee.department]![employee.location]!.count += 1
    }
    var result: [String: [String: Double]] = [:]
    for (department, locations) in departmentAverages {
        result[department] = [:]
        for (location, (totalLength, count)) in locations {
            result[department]![location] = Double(totalLength) / Double(count)
        }
    }
    return result
}
```
