How can I create a function in C++ to sort an array in descending order using selection sort algorithm?
Here is an example code:
void selectionSort(int arr[], int n){
    int i, j, min_idx;
    for (i = 0; i < n-1; i++){
        min_idx = i;
        for (j = i+1; j < n; j++)
          if (arr[j] > arr[min_idx])
            min_idx = j;
        swap(&arr[min_idx], &arr[i]);
    }
}
// Example usage:
int arr[] = {64, 25, 12, 22, 11};
int n = sizeof(arr)/sizeof(arr[0]);
selectionSort(arr, n);
// Output:
