val consonants = ('a' to 'z').filterNot(vowels.contains)
def findNextWords(word: String): List[String] = {
  val lastLetter = word.last
  val nextConsonants = consonants.filter(_ != lastLetter)
  val nextWords = nextConsonants.map(c => word + c)
  nextWords.filter(w => w != "fire" && w != "spire")
}
def generateCatalog(numWords: Int): List[List[String]] = {
  def loop(prevWord: String, count: Int): List[List[String]] = {
    if (count == 0) List(List(prevWord))
    else {
      val nextWords = findNextWords(prevWord)
      nextWords.flatMap { word =>
        loop(word, count - 1).map(words => prevWord :: words)
      }
    }
  }
  val allCatalogs = for {
    startWord <- words
    catalog <- loop(startWord, numWords - 1)
  } yield startWord :: catalog
  allCatalogs.toList
}
