Here is an example of a Swift struct that represents a point with x and y coordinates:
struct Point {
    var x: Int
    var y: Int
}
To input the data points, you could create an array of Point structs like this:
let points = [Point(x: 2, y: 3), Point(x: 4, y: 5), Point(x: 6, y: 7), Point(x: 8, y: 9), Point(x: 10, y: 11)]
Then, you could modify the Swift code for Dijkstra's algorithm to use this array of points instead of reading from an excel file. Here is an example code snippet that finds the shortest path between two given points using Dijkstra's algorithm:
struct Edge {
    var to: Int
    var weight: Int
}
func dijkstra(_ graph: [[Edge]], _ source: Int, _ dest: Int) -> [Int] {
    let INF = Int.max / 2
    var dist = [Int](repeating: INF, count: graph.count)
    var prev = [Int](repeating: -1, count: graph.count)
    var visited = [Bool](repeating: false, count: graph.count)
    dist[source] = 0
    for _ in 0..<graph.count {
        var u = -1
        for v in 0..<graph.count {
            if !visited[v] && (u == -1 || dist[v] < dist[u]) {
                u = v
            }
        }
        if dist[u] == INF {
            break
        }
        visited[u] = true
        for e in graph[u] {
            if dist[u] + e.weight < dist[e.to] {
                dist[e.to] = dist[u] + e.weight
                prev[e.to] = u
            }
        }
    }
    var path = [Int]()
    var curr = dest
    while curr != -1 {
        path.append(curr)
        curr = prev[curr]
    }
    path.reverse()
    return path
}
let points = [Point(x: 2, y: 3), Point(x: 4, y: 5), Point(x: 6, y: 7), Point(x: 8, y: 9), Point(x: 10, y: 11)]
let n = points.count
var graph = [[Edge]](repeating: [], count: n)
for i in 0..<n {
    for j in 0..<n {
        if i != j {
            let weight = abs(points[i].x - points[j].x) + abs(points[i].y - points[j].y)
            graph[i].append(Edge(to: j, weight: weight))
        }
    }
}
let source = 0
let dest = 4
let path = dijkstra(graph, source, dest)
for i in path {
    print("\(points[i].x) \(points[i].y)")
}
In this code, the array of Point structs is used to construct a weighted graph, where the weight of an edge between two points is the Manhattan distance between them. The dijkstra function takes this graph as input and returns the shortest path between the source and destination points as an array of indices into the points array. The final loop prints out the x and y coordinates of the points along the shortest path.

